SELECT 
    MIN(age) AS min_age,
    MAX(age) AS max_age,
    COUNT(*) AS total_rows,
    SUM(purchase_amount) AS grand_total
FROM customer;


-- Q10. Revenue contribution of each age group

-- Q10. Revenue contribution of each age group
-- Q10. What is the revenue contribution of each age group?

SELECT 
    age_group,
    SUM(purchase_amount) AS total_revenue
FROM (
    SELECT 
        purchase_amount,
        CASE
            WHEN age BETWEEN 18 AND 25 THEN 'Young Adult'
            WHEN age BETWEEN 26 AND 40 THEN 'Middle-aged'
            WHEN age BETWEEN 41 AND 55 THEN 'Adult'
            ELSE                            'Senior'
        END AS age_group
    FROM customer
) AS age_segments
GROUP BY age_group
ORDER BY total_revenue DESC;







